describe('Form Submission Errors Scroll Into View', () => {
  beforeEach(() => {
    cy.visit('/form-page');
  });

  it('should scroll error messages into view when form submission fails', () => {
    // Intercept the form submission API call
    cy.intercept('POST', '/api/form-submit').as('formSubmit');

    // Fill the form with invalid data
    cy.get('[data-testid="name-input"]').type('John');
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="password-input"]').type('short');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please correct the following fields');

    // Verify error message is at the top of the viewport
    cy.get('[data-testid="error-message"]').should('have.css', 'position', 'fixed');
    cy.get('[data-testid="error-message"]').should('have.css', 'top', '0');

    // Verify form fields are still visible
    cy.get('[data-testid="name-input"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');

    // Verify error message scrolls into view
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('have.css', 'scrollIntoView', 'true');

    // Verify API call was made
    cy.wait('@formSubmit').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
    });
  });

  it('should not scroll error messages when form submission succeeds', () => {
    // Intercept the form submission API call
    cy.intercept('POST', '/api/form-submit').as('formSubmit');

    // Fill the form with valid data
    cy.get('[data-testid="name-input"]').type('Jane Doe');
    cy.get('[data-testid="email-input"]').type('jane.doe@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Verify error message does not appear
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify form fields are still visible
    cy.get('[data-testid="name-input"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');

    // Verify API call was successful
    cy.wait('@formSubmit').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });
  });
});
